update public.recipes set title_en = 'Spicy Tomato Soup', instructions_en = 'INGREDIENTS:
- 4 ripe tomato
- 1 small onion
- 10 ml olive oil
- 1 tsp chilli flakes
- 1 tbsp butter
- salt

METHOD:
1. Fry the onion in the olive oil for 2 minutes.
2. Add the tomatoes and simmer for 6 minutes.
3. Add the salt, chilli flakes and 200 ml of water, then cook for 4 minutes more.
4. Stir the butter into the soup and serve.' where id = 'c7530a54-0946-41fe-a283-20d70fc067de';
update public.recipes set title_en = 'Mediterranean Quinoa Salad', instructions_en = 'INGREDIENTS:
- 100 g quinoa
- 100 g cooked chickpeas
- 1/2 cucumber
- 10 cherry tomatoes
- 30 g low-fat beyaz peynir (Turkish brined white cheese; light feta works)
- 10 olives
- 1 handful parsley
- 15 ml olive oil
- 1 juice of one lemon

METHOD:
1. Boil the quinoa in plenty of water for 15 minutes, then leave it to cool.
2. Dice all the vegetables small.
3. Combine the quinoa, chickpeas, vegetables and cheese.
4. Drizzle with olive oil and lemon juice and serve with parsley.' where id = '3971c479-ce32-4b34-9b9c-013dee1df749';
update public.recipes set title_en = 'Avocado Wholemeal Toast', instructions_en = 'INGREDIENTS:
- 2 slices wholemeal bread
- 1 ripe avocado
- 2 eggs
- 1 tbsp white vinegar
- 1 tsp lemon juice
- 1 dessertspoon extra virgin olive oil
- chilli flakes, salt and black pepper
- 5 g fresh thyme or parsley

METHOD:
1. Toast the bread in a toaster or dry pan until both sides are golden.
2. Halve the avocado and remove the stone; mash the flesh with a fork and mix in the lemon juice, salt and black pepper.
3. Bring water to the boil in a small pan; once it boils, lower the heat and add the vinegar.
4. Crack each egg into a separate bowl; make a gentle whirlpool in the water and slide the egg in slowly.
5. Poach for 2-3 minutes for a runny yolk, lift out with a slotted spoon and drain on kitchen paper.
6. Spread the mashed avocado generously over the toast and set a poached egg on each slice.
7. Scatter chilli flakes, olive oil and the chopped thyme over the top and serve immediately.' where id = 'eac3e53c-155b-413f-baac-a9a3e8d1e079';
update public.recipes set title_en = 'Avocado and Egg Wholemeal Toast', instructions_en = 'INGREDIENTS:
- 2 slices wholemeal bread
- 1/2 avocado
- 2 boiled egg
- 1/2 juice of one lemon
- chilli flakes, salt and black pepper
- fresh parsley

METHOD:
1. Toast the bread slices for 2 minutes.
2. Mash the avocado with a fork and mix in the lemon juice and salt.
3. Spread the avocado mixture over the bread.
4. Lay the sliced egg on top and serve with chilli flakes and parsley.' where id = '1fd74b61-7b93-47e9-9de3-111d1bffb6d2';
update public.recipes set title_en = 'Almond Milk Pudding', instructions_en = 'INGREDIENTS:
- 250 ml milk
- 25 g rice flour
- 30 g sugar
- 30 g almonds
- 1 packet vanilla

METHOD:
1. Slake the rice flour with 50 ml of cold milk.
2. Bring the remaining milk to the boil and add the sugar.
3. Add the rice flour mixture and stir for 6 minutes until it thickens.
4. Divide between bowls and finish with vanilla and almonds.' where id = 'a4b2407b-b8c5-42c9-897a-9b278cf09a80';
update public.recipes set title_en = 'Gardener''s Salad', instructions_en = 'INGREDIENTS:
- 2 handfuls lettuce
- 1 tomato
- 1 cucumber
- 1 small green pepper
- 1 small carrot
- 10 ml olive oil

METHOD:
1. Combine all the vegetables in a bowl.
2. Add the olive oil.
3. Season with salt and toss lightly.
4. Serve cold.' where id = '8ee45d41-201d-4070-8125-82572e27e368';
update public.recipes set title_en = 'Vanilla Yogurt with Honey', instructions_en = 'INGREDIENTS:
- 200 g strained yogurt (Turkish süzme; Greek yogurt is the same thing)
- 1 packet vanilla
- 1 tbsp honey
- 15 g walnuts
- 1 pinch cinnamon

METHOD:
1. Stir the vanilla through the yogurt.
2. Spoon into a bowl and drizzle the honey over.
3. Scatter the walnuts.
4. Finish with cinnamon and serve.' where id = '802c2e46-5125-42f5-9587-0b0b3c0f2ce6';
update public.recipes set title_en = 'Lor Cheese with Honey and Walnuts', instructions_en = 'INGREDIENTS:
- 100 g lor cheese (fresh Turkish whey cheese; ricotta is the closest substitute)
- 1 tbsp honey
- 15 g walnuts
- 1 pinch cinnamon
- 1 slice wholemeal bread

METHOD:
1. Spoon the lor cheese into a bowl.
2. Add the walnuts on top.
3. Drizzle the honey over.
4. Finish with cinnamon and serve with bread.' where id = '01115b20-4d27-47af-9ab4-7b7bb0896688';
update public.recipes set title_en = 'Strained Yogurt with Honey and Walnuts', instructions_en = 'INGREDIENTS:
- 200 g strained yogurt (Turkish süzme; Greek yogurt is the same thing)
- 1 tbsp honey
- 15 g walnut halves
- 1 pinch cinnamon

METHOD:
1. Spoon the yogurt into a bowl.
2. Add the honey and walnuts on top.
3. Finish with cinnamon and serve.' where id = '199c2d0f-6762-4ab5-a8e9-43bf797836ce';
update public.recipes set title_en = 'Honey Cinnamon French Toast', instructions_en = 'INGREDIENTS:
- 2 slices wholemeal bread
- 1 eggs
- 60 ml milk
- 15 g butter
- 2 tbsp honey
- 1 tsp cinnamon

METHOD:
1. Whisk the eggs, milk and cinnamon together.
2. Dip the bread slices in the mixture.
3. Fry each side in the butter for 2 minutes.
4. Drizzle the honey over and serve warm.' where id = '954637ff-d82c-4895-b007-f4a07a5be8be';
update public.recipes set title_en = 'Bazlama Pan Toastie', instructions_en = 'INGREDIENTS:
- 1 bazlama (Turkish flatbread; pita or naan works)
- 40 g beyaz peynir (Turkish brined white cheese; feta works)
- 1 tomato
- 5 olives
- a few fresh mint leaves

METHOD:
1. Split the bazlama through the middle and spread the cheese over the cut face.
2. Add the tomato slices and olives.
3. Heat in a covered pan for 3 minutes.
4. Garnish with mint and serve.' where id = 'f6a99c06-ec20-4ded-ad03-c922b5ce6924';
update public.recipes set title_en = 'Beyaz Peynir with Honey', instructions_en = 'INGREDIENTS:
- 100 g beyaz peynir (Turkish brined white cheese; feta works)
- 1 tbsp honey
- 15 g walnuts
- 1 pinch cinnamon
- 1 slice wholemeal bread

METHOD:
1. Put the beyaz peynir in a bowl and crumble it.
2. Stir in the honey and walnuts.
3. Finish with cinnamon.
4. Serve alongside a slice of bread.' where id = 'c9033734-c8da-49e0-9171-46d203b0c410';
update public.recipes set title_en = 'Beyaz Peynir Crêpes', instructions_en = 'INGREDIENTS:
- 1 eggs
- 60 g flour
- 150 ml milk
- 60 g beyaz peynir (Turkish brined white cheese; feta works)
- 5 g butter
- 1 tbsp chopped parsley

METHOD:
1. Whisk the eggs, flour and milk until smooth.
2. Cook thin crêpes in an oiled pan.
3. Spread the cheese and parsley over half of each crêpe.
4. Fold in half, heat for 1 minute more and serve.' where id = 'ead9815b-2916-4f6d-a6a2-ca4da7e063ad';
update public.recipes set title_en = 'Simple Pasta with Beyaz Peynir', instructions_en = 'INGREDIENTS:
- 100 g pasta
- 60 g beyaz peynir (Turkish brined white cheese; feta works)
- 10 ml olive oil
- 1 tbsp dried mint
- salt

METHOD:
1. Boil the pasta in salted water and drain it.
2. Warm the olive oil in the same pan.
3. Return the pasta, add the cheese and toss together.
4. Garnish with mint and serve hot.' where id = '1b35914c-3679-4653-ba66-6712fe4580ec';
update public.recipes set title_en = 'Wholemeal Toastie with Beyaz Peynir', instructions_en = 'INGREDIENTS:
- 2 slices wholemeal bread
- 60 g beyaz peynir (Turkish brined white cheese; feta works)
- 1 tomato
- 5 olives
- 1 dessertspoon olive oil
- a few fresh mint leaves

METHOD:
1. Brush one side of each bread slice with olive oil.
2. Crumble the cheese and spread it evenly over the inner faces.
3. Toast in a two-sided sandwich press for 3-4 minutes.
4. Serve with tomato slices, olives and mint.' where id = '3a214fcf-8431-446d-a3c7-c79477ed35c1';
update public.recipes set title_en = 'Rice Pilaf with Beef Sauté', instructions_en = 'INGREDIENTS:
- 60 g rice
- 120 g diced beef
- 1 small onion
- 5 ml olive oil
- 1 tbsp tomato paste
- salt

METHOD:
1. Cook the rice in salted water for 12 minutes and drain.
2. Fry the beef in the olive oil for 4 minutes.
3. Add the onion and tomato paste and cook for 6 minutes more with 100 ml of water.
4. Plate the rice and lay the beef over it.' where id = '69fe7821-da0d-4fde-b922-1bff725ba374';
update public.recipes set title_en = 'Rice Pilaf with Yogurt', instructions_en = 'INGREDIENTS:
- 80 g rice
- 200 g strained yogurt (Turkish süzme; Greek yogurt is the same thing)
- 1 tbsp butter
- salt

METHOD:
1. Rinse the rice and soak it in hot water for 10 minutes.
2. Melt the butter in a pan, add the rice and fry for 1 minute.
3. Add 200 ml of hot water and the salt, cover and cook for 12 minutes.
4. Let the pilaf rest and serve with the yogurt.' where id = 'cfbd5f33-c888-41da-bfff-19dac7bb5464';
update public.recipes set title_en = 'Beef and Pea Stew', instructions_en = 'INGREDIENTS:
- 200 g peas
- 100 g diced beef
- 1 carrot
- 1 small onion
- 5 ml olive oil
- salt

METHOD:
1. Fry the beef in the olive oil for 4 minutes.
2. Add the onion and carrot and cook for 3 minutes more.
3. Add the peas and 150 ml of hot water.
4. Cover, cook for 6 minutes, season with salt and serve.' where id = '5e07f2d7-d319-49df-9594-27625e023968';
update public.recipes set title_en = 'Beef Fillet Burrito', instructions_en = 'INGREDIENTS:
- 1 large wholemeal tortilla
- 160 g grilled beef fillet
- 80 g brown rice
- 80 g kidney beans
- 30 g cheddar cheese
- 1/2 avocado
- 2 tbsp salsa

METHOD:
1. Combine the rice and kidney beans in a bowl.
2. Warm the tortilla lightly in a pan.
3. Lay the rice and bean mixture, beef, cheese, avocado and salsa down the middle.
4. Fold the ends in first, then roll it tightly.
5. Fry each side in a hot pan for 1 minute until golden.' where id = '2cdccaa8-2a84-480c-b763-a58f7098a206';
update public.recipes set title_en = 'Date and Walnut Balls', instructions_en = 'INGREDIENTS:
- 8 dates
- 30 g walnuts
- 15 g desiccated coconut
- 1 tbsp unsweetened cocoa

METHOD:
1. Blitz the dates and walnuts in a food processor.
2. Roll the mixture into walnut-sized balls.
3. Coat the balls first in cocoa, then in desiccated coconut.
4. Chill for 5 minutes and serve.' where id = 'bf0de0db-b6d4-4097-a476-5e885f7df580';
update public.recipes set title_en = 'Caramelised Banana with Walnuts', instructions_en = 'INGREDIENTS:
- 2 banana
- 15 g butter
- 1 tbsp honey
- 20 g walnuts
- 1 pinch cinnamon

METHOD:
1. Melt the butter in a pan and fry the banana slices for 2 minutes a side.
2. Drizzle the honey down the side of the pan.
3. Lift the bananas onto a plate.
4. Scatter the walnuts and cinnamon over and serve warm.' where id = 'a0f69eb5-d78f-4343-ac48-2f3887b6cb07';
update public.recipes set title_en = 'Yogurt Dessert with Walnuts', instructions_en = 'INGREDIENTS:
- 200 g strained yogurt (Turkish süzme; Greek yogurt is the same thing)
- 20 g walnuts
- 1 tbsp honey
- 1 pinch cinnamon
- 5 g desiccated coconut

METHOD:
1. Spoon the yogurt into a bowl.
2. Add the honey and walnuts on top.
3. Scatter the cinnamon and desiccated coconut.
4. Serve immediately.' where id = '0a5aa59a-d467-4678-a7ec-88e7d2508a8b';
update public.recipes set title_en = 'Vegan Chia Pancakes', instructions_en = 'INGREDIENTS:
- 80 g wholemeal flour
- 15 g chia seeds
- 200 ml almond milk
- 1 dessertspoon baking powder
- 15 g maple syrup
- 1 dessertspoon vanilla extract
- 80 g fresh blackberries

METHOD:
1. Soak the chia seeds in 45 ml of water for 5 minutes until they swell.
2. Whisk the flour, baking powder, milk, maple syrup, vanilla and the chia gel until smooth.
3. Cook each pancake in a non-stick pan over medium heat for 2 minutes.
4. Stack the pancakes, scatter the blackberries over and serve.' where id = '06619310-0964-4c14-b9bd-76e915fc2379';
update public.recipes set title_en = 'Chia Seed Pudding', instructions_en = 'INGREDIENTS:
- 40 g chia seeds
- 300 ml unsweetened almond milk
- 15 g maple syrup
- 1 dessertspoon vanilla extract
- 80 g fresh strawberries
- 20 g almonds

METHOD:
1. Stir the chia seeds, almond milk, maple syrup and vanilla together in a jar.
2. Refrigerate for at least 4 hours, preferably overnight.
3. In the morning, loosen it with a fork and transfer to a bowl.
4. Scatter the strawberries and almonds over and serve.' where id = '609271de-0d7b-4936-a958-c036c17ce1dc';
update public.recipes set title_en = 'Raw Vegetable Breakfast Plate', instructions_en = 'INGREDIENTS:
- 1 cucumber
- 1 tomato
- 5 olives
- 40 g beyaz peynir (Turkish brined white cheese; feta works)
- 5 ml olive oil
- a few fresh mint leaves

METHOD:
1. Arrange the vegetables on a plate.
2. Set the beyaz peynir and olives to one side.
3. Drizzle olive oil over the top.
4. Garnish with mint and serve.' where id = 'f7bdb1c2-8d2c-49df-81ea-ad6cd959b8b4';
update public.recipes set title_en = 'Crudités with Yogurt Dip', instructions_en = 'INGREDIENTS:
- 1 carrot
- 1 cucumber
- 1 green pepper
- 150 g strained yogurt (Turkish süzme; Greek yogurt is the same thing)
- 1 clove garlic
- 1 tsp dried mint

METHOD:
1. Cut the vegetables into fingers and arrange them on a plate.
2. Stir the garlic and mint through the yogurt.
3. Put the dip on the plate in a small bowl.
4. Serve immediately.' where id = '9ca7c29f-a84c-4eda-857c-0691ae8b3cf8';
update public.recipes set title_en = 'Chocolate Chia Pudding', instructions_en = 'INGREDIENTS:
- 35 g chia seeds
- 250 ml unsweetened almond milk
- 10 g unsweetened cocoa powder
- 15 g maple syrup
- 1 dessertspoon vanilla extract
- 60 g strawberries

METHOD:
1. Whisk the chia seeds, almond milk, cocoa, maple syrup and vanilla together in a jar.
2. Refrigerate for at least 4 hours, preferably overnight.
3. Loosen it with a fork before serving.
4. Set the strawberries on top and serve.' where id = '6080c19f-9ab2-4b03-b7bb-58714d7af12e';
update public.recipes set title_en = 'Chocolate Banana Protein Shake', instructions_en = 'INGREDIENTS:
- 1 banana
- 300 ml semi-skimmed milk
- 30 g chocolate whey protein powder
- 5 g cocoa powder
- 100 g ice

METHOD:
1. Put all the ingredients in a blender.
2. Blend on high for 45 seconds until smooth.
3. Pour into a tall glass.
4. Dust with cocoa powder if you like and drink immediately.' where id = '480dd7a1-fc9b-457f-93d2-2528f0366e9c';
update public.recipes set title_en = 'Chocolate Protein Pudding', instructions_en = 'INGREDIENTS:
- 200 g strained yogurt (Turkish süzme; Greek yogurt is the same thing)
- 25 g chocolate whey protein powder
- 5 g unsweetened cocoa powder
- 15 g honey
- 10 g raw almonds

METHOD:
1. Whisk the yogurt, protein powder and cocoa powder until even.
2. Add the honey and stir again.
3. Transfer to a serving bowl and rest in the fridge for 30 minutes.
4. Scatter the roughly chopped almonds over and serve.' where id = '4363943a-3361-421a-8cc3-3307ca0257a2';
update public.recipes set title_en = 'Chocolate Oat Balls', instructions_en = 'INGREDIENTS:
- 80 g rolled oats
- 2 tbsp unsweetened cocoa
- 2 tbsp honey
- 20 g desiccated coconut
- 15 g peanut butter

METHOD:
1. Knead the oats, cocoa, honey and peanut butter together.
2. Roll the mixture into walnut-sized balls.
3. Coat them in desiccated coconut.
4. Chill for 5 minutes and serve.' where id = '03e58bea-2402-4487-9b18-c3684ba0f036';
update public.recipes set title_en = 'Çılbır — Poached Eggs over Garlic Yogurt', instructions_en = 'INGREDIENTS:
- 2 eggs
- 200 g strained yogurt (Turkish süzme; Greek yogurt is the same thing)
- 1 clove garlic
- 15 g butter
- 1 tsp chilli flakes
- salt

METHOD:
1. Stir the crushed garlic and salt through the yogurt and spread it over a plate.
2. Crack the eggs into boiling water, poach for 3 minutes and drain.
3. Set the eggs on the yogurt.
4. Melt the butter and bloom the chilli flakes in it, then pour it over and serve.' where id = '094b6838-66f7-4f54-a67a-6044c70d8407';
update public.recipes set title_en = 'Scrambled Eggs with Pastırma', instructions_en = 'INGREDIENTS:
- 3 eggs
- 30 g pastırma (air-dried spiced beef; bresaola is the closest substitute)
- 5 ml butter
- 1 tbsp milk
- salt and black pepper

METHOD:
1. Fry the pastırma in a pan for 1 minute.
2. Beat the eggs with the milk and add the seasoning.
3. Pour over the pastırma and scramble for 3 minutes.
4. Plate and serve with the butter.' where id = '3de1e0e6-e7be-4c73-9129-c5ca0af644e8';
update public.recipes set title_en = 'Crispy Fried Egg Sandwich', instructions_en = 'INGREDIENTS:
- 2 slices wholemeal bread
- 2 eggs
- 5 ml butter
- 1 leaf lettuce
- 1 slice tomato
- salt

METHOD:
1. Fry the eggs in the butter for 3 minutes.
2. Toast the bread slices lightly.
3. Lay the egg, lettuce and tomato on one slice.
4. Season with salt, close with the other slice and serve.' where id = '579c99c8-5802-4707-98e7-36fe6438d3d3';
update public.recipes set title_en = 'Beef Fillet in Tomato Sauce', instructions_en = 'INGREDIENTS:
- 150 g beef fillet
- 2 ripe tomato
- 1 tbsp tomato paste
- 1 small onion
- 10 ml olive oil
- salt

METHOD:
