update public.recipes set title_en = 'Tomato Rice Pilaf', instructions_en = 'INGREDIENTS:
- 80 g rice
- 1 ripe tomato
- 1 small onion
- 1 tbsp butter
- 1 tbsp tomato paste
- salt

METHOD:
1. Fry the onion in the butter for 2 minutes.
2. Add the tomato paste and tomatoes and cook for 2 minutes more.
3. Add the rice and fry for 1 minute.
4. Add 200 ml of hot water and the salt, cover and cook for 12 minutes.' where id = '09e92bc4-5133-4776-b5cc-46d748b3a8cd';
update public.recipes set title_en = 'Simple Chicken with Tomatoes', instructions_en = 'INGREDIENTS:
- 200 g chicken breast
- 2 ripe tomato
- 1 green pepper
- 5 ml olive oil
- salt and black pepper

METHOD:
